// Factory pattern: creates objects without exposing instantiation logic
public class PaymentFactory {
    public Payment createPayment(String type) {
        return switch (type) {
            case "CREDIT_CARD" -> new CreditCardPayment();
            case "UPI" -> new UpiPayment();
            case "NET_BANKING" -> new NetBankingPayment();
            default -> throw new IllegalArgumentException("Unknown payment type");
        }; // Java 17 switch expression
    }
}

interface Payment {
    void processPayment(double amount);
}

record CreditCardPayment() implements Payment {
    public void processPayment(double amount) {
        System.out.println("Processing credit card: " + amount);
    }
}

// Usage in a cart service
var factory = new PaymentFactory();
var payment = factory.createPayment("UPI"); // caller doesn't know implementation details
payment.processPayment(499.99);

// CREATIONAL: Singleton - one shared instance
@Service // Spring creates single instance by default
public class CartService {
    private final CartRepository repository;
    public CartService(CartRepository repository) {
        this.repository = repository;
    }
}

// STRUCTURAL: Decorator - adds behavior without changing original
public class LoggingCartService implements CartOperations {
    private final CartOperations delegate;
    public void addItem(Long cartId, Item item) {
        System.out.println("Adding item: " + item);
        delegate.addItem(cartId, item); // wraps original behavior
    }
}

// BEHAVIORAL: Strategy - swaps algorithms at runtime
interface DiscountStrategy {
    double applyDiscount(double price);
}

record PercentageDiscount(int percent) implements DiscountStrategy {
    public double applyDiscount(double price) {
        return price * (1 - percent / 100.0);
    }
}

