// PATTERN: you write and call the code yourself (Singleton)
class Config {
    private static final Config INSTANCE = new Config();
    private Config() {}
    static Config get() { return INSTANCE; }   // YOU call this
}

// FRAMEWORK: Spring writes the wiring and calls YOUR code (Inversion of Control)
@Service                                    // Spring creates ONE instance (singleton scope)
class CartService {
    private final CartRepository repo;
    CartService(CartRepository repo) {       // Spring injects this - you never call new
        this.repo = repo;
    }
}
// Rule of thumb: with a pattern your code calls in; with a framework it calls you.
