// STRUCTURAL (Decorator): compose objects to add behavior by wrapping
interface CartOps { void addItem(String item); }
class RealCart implements CartOps { public void addItem(String i){ /* save */ } }
class LoggingCart implements CartOps {            // wraps another CartOps
    private final CartOps inner;
    LoggingCart(CartOps c){ this.inner = c; }
    public void addItem(String i){ System.out.println("log " + i); inner.addItem(i); }
}

// BEHAVIORAL (Strategy): swap interchangeable algorithms at runtime
interface Discount { double apply(double price); }
class PercentOff implements Discount { public double apply(double p){ return p * 0.9; } }
