// SINGLETON: Spring creates one instance of this bean
@Service
public class CartService {
    private final CartRepository repository; // injected dependency

    public CartService(CartRepository repository) {
        this.repository = repository; // constructor injection
    }
}

// PROXY: @Transactional creates proxy with transaction logic
@Transactional // Spring wraps this method in transaction boundary
public void checkout(Long cartId) {
    var cart = repository.findById(cartId).orElseThrow();
    // Spring starts transaction before this line
    processPayment(cart);
    clearCart(cartId);
    // Spring commits transaction after this line
}

