// ALGORITHM: a concrete, deterministic procedure (binary search)
static int binarySearch(int[] a, int key) {
    int lo = 0, hi = a.length - 1;
    while (lo <= hi) {
        int mid = (lo + hi) >>> 1;          // exact steps, same every time
        if (a[mid] == key) return mid;
        if (a[mid] < key)  lo = mid + 1;
        else               hi = mid - 1;
    }
    return -1;
}

// DESIGN PATTERN: a structural template you adapt (Strategy holds algorithms)
interface SearchStrategy { int search(int[] a, int key); }
class BinarySearchStrategy implements SearchStrategy {
    public int search(int[] a, int key) { return binarySearch(a, key); }
}
// The algorithm is the method body; the pattern is the class design around it.
