// ANTI-PATTERN: God Class - one class doing everything
@Service
public class CartGodClass {
    // handles HTTP, business logic, database, email, logging...
    public void processCheckout(HttpServletRequest request) {
        var cartId = Long.parseLong(request.getParameter("id"));
        // database access
        var cart = jdbcTemplate.queryForObject("SELECT * FROM carts WHERE id = ?", cartId);
        // payment processing
        paymentGateway.charge(cart.getTotal());
        // email sending
        emailService.sendConfirmation(cart.getUserEmail());
        // logging
        System.out.println("Processed cart: " + cartId);
        // all in one class!
    }
}

